/**
 * Crisis resources — offline, always reachable, safe-messaging compliant.
 *
 * Industry expectation (APA app-evaluation model; #chatsafe guidelines):
 * crisis help must be reachable within one or two interactions from any
 * screen, must work offline (numbers cached in the app binary, no API
 * round-trip), and must never be generated by AI. This screen is static
 * content with direct call/text/chat actions. Nothing here diagnoses,
 * tracks, or alerts anyone — it just puts real humans one tap away.
 *
 * Call anxiety is the top barrier to using a hotline, so the screen says
 * plainly what calling is like. Locale awareness (device region via Intl —
 * no new dependencies): outside the US, findahelpline.com leads and the
 * US-only services say so honestly. Every open failure still falls back to
 * speaking the number aloud — a dead tap here is the worst possible bug.
 */
import React from "react";
import { Alert, Linking, Platform, ScrollView, StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { useTheme } from "../theme";
import { t as tr } from "../strings";

/** Texting a crisis line uses a different query separator per platform:
 *  Android's "?body=" is silently dropped by iOS (which wants "&body="),
 *  and "HOME" pre-filled is the whole point of the shortcut. */
function crisisTextUrl(): string {
  return `sms:741741${Platform.select({ ios: "&body=HOME", default: "?body=HOME" })}`;
}

/** Every external open can reject (no dialer, no browser, a simulator) —
 *  and a dead tap on THIS screen is the worst possible failure. Fall back
 *  to telling the user the number/address itself. */
function openExternal(url: string, fallback: string): void {
  Linking.openURL(url).catch(() => {
    Alert.alert(tr("crisis.openFailedTitle"), fallback);
  });
}

/** The device's region from its locale ("en-US" → "US"), or null when the
 *  platform won't say. No native module needed; failure keeps US-first. */
export function deviceRegion(): string | null {
  try {
    const locale = Intl.DateTimeFormat().resolvedOptions().locale;
    const match = /[-_]([A-Za-z]{2})\b/.exec(locale);
    // Stryker disable next-line OptionalChaining: match is either null (the mutant's throw is caught and returns null — the same value) or a match whose group 1 always participates, so both forms are observably identical
    const region = match?.[1];
    return region ? region.toUpperCase() : null;
  } catch {
    return null;
  }
}

function ActionButton({
  label,
  detail,
  onPress,
  theme,
}: {
  label: string;
  detail: string;
  onPress: () => void;
  theme: ReturnType<typeof useTheme>;
}) {
  return (
    <TouchableOpacity
      style={[
        styles.action,
        {
          backgroundColor: theme.colors.card,
          borderRadius: theme.radius.lg,
          minHeight: theme.minTouch,
        },
      ]}
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={tr("crisis.actionA11y", { label, detail })}
    >
      <View style={{ flex: 1 }}>
        <Text style={[styles.actionLabel, { color: theme.colors.text }]}>{label}</Text>
        <Text style={[styles.actionDetail, { color: theme.colors.muted, fontSize: 13 }]}>{detail}</Text>
      </View>
      <Text style={[styles.actionGo, { color: theme.colors.accent }]}>{tr("crisis.go")}</Text>
    </TouchableOpacity>
  );
}

/** `region` is injectable for tests; production callers leave it to the
 *  device locale. */
export function CrisisScreen({ region }: { region?: string }): React.JSX.Element {
  const t = useTheme();
  const effectiveRegion = region ?? deviceRegion();
  // null (unknown) keeps the US-first layout — the services are US-based,
  // and a misdetection must never hide them from a US user mid-crisis.
  const usFirst = effectiveRegion === null || effectiveRegion === "US";

  const usServices = (
    <>
      <ActionButton
        label={tr("crisis.call988")}
        detail={tr("crisis.call988.detail")}
        onPress={() => openExternal("tel:988", tr("crisis.call988.fallback"))}
        theme={t}
      />
      <ActionButton
        label={tr("crisis.text741741")}
        detail={tr("crisis.text741741.detail")}
        onPress={() => openExternal(crisisTextUrl(), tr("crisis.text741741.fallback"))}
        theme={t}
      />
      <ActionButton
        label={tr("crisis.chat")}
        detail={tr("crisis.chat.detail")}
        onPress={() => openExternal("https://988lifeline.org/chat", tr("crisis.chat.fallback"))}
        theme={t}
      />
      <ActionButton
        label={usFirst ? tr("crisis.emergency.us") : tr("crisis.emergency")}
        detail={tr("crisis.emergency.detail")}
        onPress={() => openExternal("tel:911", tr("crisis.emergency.fallback"))}
        theme={t}
      />
    </>
  );

  const helpline = (
    <TouchableOpacity
      style={[styles.link, { minHeight: t.minTouch, justifyContent: "center" }]}
      hitSlop={t.touchSlop}
      onPress={() => openExternal("https://findahelpline.com", tr("crisis.findhelpline.fallback"))}
      accessibilityRole="link"
      accessibilityLabel={tr("crisis.findhelpline.detail")}
    >
      <Text style={[styles.linkText, { color: t.colors.accent }]}>{tr("crisis.findhelpline")}</Text>
    </TouchableOpacity>
  );

  return (
    <ScrollView
      style={[styles.container, { backgroundColor: t.colors.bg }]}
      contentContainerStyle={{ padding: t.spacing.xl, gap: 14 }}
    >
      <Text style={[styles.headline, { color: t.colors.text }]}>{tr("crisis.title")}</Text>
      <Text style={[styles.body, { color: t.colors.body }]}>{tr("crisis.subtitle")}</Text>
      <Text style={[styles.body, { color: t.colors.body }]}>{tr("crisis.whatToExpect")}</Text>

      {usFirst ? (
        <>
          {usServices}
          <Text style={[styles.body, { color: t.colors.body }]}>{tr("crisis.localeNote")}</Text>
          {helpline}
        </>
      ) : (
        <>
          <Text style={[styles.body, { color: t.colors.body }]}>{tr("crisis.regionNote")}</Text>
          {helpline}
          <Text style={[styles.body, { color: t.colors.body }]}>{tr("crisis.usServicesNote")}</Text>
          {usServices}
        </>
      )}

      <View style={[styles.divider, { backgroundColor: t.colors.border }]} />
      <Text style={[styles.note, { color: t.colors.muted }]}>{tr("crisis.disclaimer")}</Text>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  headline: { fontSize: 20, fontWeight: "700", lineHeight: 27 },
  body: { fontSize: 15, lineHeight: 22 },
  action: {
    flexDirection: "row",
    alignItems: "center",
    padding: 16,
    gap: 12,
  },
  actionLabel: { fontSize: 16, fontWeight: "700" },
  actionDetail: { marginTop: 3, lineHeight: 18 },
  actionGo: { fontSize: 14, fontWeight: "700" },
  link: { padding: 4 },
  linkText: { fontSize: 15, fontWeight: "600" },
  divider: { height: 1, marginTop: 6 },
  note: { fontSize: 12, lineHeight: 18 },
});
